using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatClientBuilder =>
    chatClientBuilder.UseOpenAIChatClient("gpt-4o-mini-2024-07-18"));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Description = "An AI research assistant that searches the web for information and takes notes to build a comprehensive summary.",
    Instructions = """
        You are a research assistant. When given a topic:
        1. Use the web_search tool to find relevant information (perform multiple searches with different queries).
        2. Use the take_note tool to record key findings.
        3. After gathering enough information, provide a comprehensive summary of your findings.
        Be thorough but concise. Cite your sources where possible.
        """,
    Tools = [
        AIFunctionFactory.Create(WebSearch, "web_search", "Search the web for information on a given query"),
        AIFunctionFactory.Create(TakeNote, "take_note", "Save a research note with a title and content"),
    ],
};

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine($"\nResearching: {topic}\n");

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 10,
    };

    await foreach (var message in agent.InvokeStreamingAsync(history, options))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine("\n");
}

// --- Tool Implementations ---

static List<string> notes = [];

[Description("Search the web for information on a given query. Returns a list of search results.")]
static string WebSearch([Description("The search query")] string query)
{
    // Simulated web search results for demonstration purposes.
    // In production, replace with a real search API (e.g., Bing Search, Google Custom Search).
    Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

    return $$"""
        Search results for "{{query}}":
        1. Wikipedia - Overview article covering key aspects of {{query}}. Source: https://en.wikipedia.org/wiki/{{Uri.EscapeDataString(query)}}
        2. Research Paper - Recent academic findings related to {{query}}. Source: https://arxiv.org/search/?query={{Uri.EscapeDataString(query)}}
        3. News Article - Latest developments in {{query}}. Source: https://news.example.com/{{Uri.EscapeDataString(query)}}
        """;
}

[Description("Save a research note with a title and content for later summarization.")]
static string TakeNote(
    [Description("The title of the note")] string title,
    [Description("The content of the note")] string content)
{
    Console.WriteLine($"  [Tool] Note saved: \"{title}\"");
    notes.Add($"## {title}\n{content}");
    return $"Note saved successfully. Total notes: {notes.Count}";
}

